"use client";
import React from "react";
import { motion } from "framer-motion";

const DisplayCards = ({ cards = [] }) => {
  return (
    <div className="relative w-full max-w-4xl mx-auto">
      <div className="relative flex items-center justify-center min-h-[400px]">
        {cards.map((card, index) => {
          const isFirst = index === 0;
          const isSecond = index === 1;
          const isThird = index === 2;

          return (
            <motion.div
              key={index}
              initial={{ opacity: 0, y: 60 }}
              whileInView={{ opacity: 1, y: 0 }}
              viewport={{ once: true }}
              transition={{ duration: 0.6, delay: index * 0.15, ease: [0.25, 0.46, 0.45, 0.94] }}
              whileHover={isFirst ? { y: -40 } : isSecond ? { y: -10 } : { y: 10 }}
              className="absolute w-full max-w-sm transition-transform duration-500 ease-out cursor-pointer"
              style={{
                zIndex: cards.length - index,
                x: isFirst ? 0 : isSecond ? "12%" : "24%",
                y: isFirst ? 0 : isSecond ? "8%" : "16%",
              }}
            >
              {/* Card Container */}
              <div
                className="relative rounded-2xl overflow-hidden"
                style={{
                  background: card.bgGradient || "linear-gradient(135deg, #1a080a 0%, #2a1520 100%)",
                  border: `1px solid ${card.accentColor || "#d4af37"}40`,
                }}
              >
                {/* Top accent bar */}
                <div
                  className="absolute top-0 left-0 right-0 h-1"
                  style={{ background: card.accentColor || "#d4af37" }}
                />

                {/* Grayscale overlay for background cards */}
                {!isFirst && (
                  <div
                    className="absolute inset-0 z-20 transition-opacity duration-700"
                    style={{
                      background: "linear-gradient(180deg, rgba(26,8,10,0.6) 0%, rgba(26,8,10,0.8) 100%)",
                    }}
                  />
                )}

                {/* Card Content */}
                <div className="relative z-10 p-6">
                  {/* Icon */}
                  <div
                    className="w-10 h-10 rounded-lg flex items-center justify-center mb-4"
                    style={{
                      background: `${card.accentColor || "#d4af37"}20`,
                      color: card.accentColor || "#d4af37",
                    }}
                  >
                    {card.icon}
                  </div>

                  {/* Badge */}
                  <div className="mb-3">
                    <span
                      className="inline-block text-xs font-semibold uppercase tracking-wider px-2 py-1 rounded-md"
                      style={{
                        background: `${card.accentColor || "#d4af37"}20`,
                        color: card.accentColor || "#d4af37",
                      }}
                    >
                      {card.badge}
                    </span>
                  </div>

                  {/* Title */}
                  <h3 className="text-xl font-semibold text-white mb-2" style={{ fontFamily: "Cormorant Garamond, serif" }}>
                    {card.title}
                  </h3>

                  {/* Description */}
                  <p className="text-sm leading-relaxed mb-4" style={{ color: "rgba(255,255,255,0.6)" }}>
                    {card.description}
                  </p>

                  {/* Date */}
                  <p className="text-xs" style={{ color: "rgba(255,255,255,0.4)" }}>
                    {card.date}
                  </p>
                </div>

                {/* Bottom decorative corner */}
                <div
                  className="absolute bottom-0 right-0 w-20 h-20"
                  style={{
                    borderBottom: `2px solid ${card.accentColor || "#d4af37"}`,
                    borderRight: `2px solid ${card.accentColor || "#d4af37"}`,
                    opacity: 0.3,
                  }}
                />
              </div>
            </motion.div>
          );
        })}
      </div>
    </div>
  );
};

export default DisplayCards;
